import{_ as i,a0 as a,w as s,s as l,ao as u,I as p,x as e,a1 as o,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（六） | LCTT x X-CMD","titleTemplate":false,"description":"安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（六） | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（六） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（六） | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/30 Things to Do After Minimal RHEL or CentOS 7 Installation--6","title":"安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（六）","tag":"201505","desc":""},"relativePath":"201505/30 Things to Do After Minimal RHEL or CentOS 7 Installation--6.md","filePath":"[post].md"}'),m={name:"201505/30 Things to Do After Minimal RHEL or CentOS 7 Installation--6.md"};function d(g,t,b,c,w,f){const n=a("Link");return s(),l("div",null,[t[13]||(t[13]=u(`<h1 id="安裝完最小化-rhel-centos-7-後需要做的-30-件事情-六" tabindex="-1">安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（六） <a class="header-anchor" href="#安裝完最小化-rhel-centos-7-後需要做的-30-件事情-六" aria-label="Permalink to “安裝完最小化 RHEL/CentOS 7 後需要做的 30 件事情（六）”">​</a></h1><h3 id="_30-用密碼保護-grub" tabindex="-1">30. 用密碼保護 GRUB <a class="header-anchor" href="#_30-用密碼保護-grub" aria-label="Permalink to “30. 用密碼保護 GRUB”">​</a></h3><p>用密碼保護你的 boot 引導程序這樣你就可以在啓動時獲得額外的安全保障。同時你也可以在實物層面獲得保護。通過在引導時給 GRUB 加鎖防止任何無授權訪問來保護你的服務器。</p><p>首先備份兩個文件，這樣如果有任何錯誤出現，你可以有回滾的選擇。備份 ‘/etc/grub2/grub.cfg’ 為 ‘/etc/grub2/grub.cfg.old’。</p><pre><code># cp /boot/grub2/grub.cfg /boot/grub2/grub.cfg.old
</code></pre><p>同樣，備份 ‘/etc/grub.d/10_linux’ 為 ‘/etc/grub.d/10_linux.old’。</p><pre><code># cp /etc/grub.d/10_linux /etc/grub.d/10_linux.old
</code></pre><p>打開文件 ‘/etc/grub.d/10_linux’ 並在文件末尾添加下列行。</p><pre><code>cat &lt;&lt;EOF
set superusers=&quot;tecmint&quot;
Password tecmint avi@123
EOF
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Password-Protect-Grub.png" alt="密碼保護 Grub"></p><p><em>密碼保護 Grub</em></p><p>注意在上面的文件中，用你自己的用户名和密碼代替 “tecmint” 和 “avi@123”。</p><p>現在通過運行下面的命令生成新的 grub.cfg 文件。</p><pre><code># grub2-mkconfig --output=/boot/grub2/grub.cfg
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Generate-Grub-File.jpeg" alt="生成 Grub 文件"></p><p><em>生成 Grub 文件</em></p><p>創建 grub.cfg 文件之後，重啓機器並敲擊 ‘e’ 進入編輯。你會發現它會要求你輸入 “有效驗證” 來編輯 boot 菜單。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Edit-Boot-Menu.jpeg" alt="有密碼保護的 Boot 菜單"></p><p><em>有密碼保護的 Boot 菜單</em></p><p>輸入登錄驗證之後，你就可以編輯 grub boot 菜單。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Grub-Menu-Edit.jpeg" alt="Grub 菜單文件"></p><p><em>Grub 菜單文件</em></p><p>你也可以用加密的密碼代替上一步的明文密碼。首先按照下面推薦的生成加密密碼。</p><pre><code># grub2-mkpasswd-pbkdf2

[兩次輸入密碼]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Generate-Encrypted-Grub-Password.jpeg" alt="生成加密的 Grub 密碼"></p><p><em>生成加密的 Grub 密碼</em></p><p>打開 ‘/etc/grub.d/10_linux’ 文件並在文件末尾添加下列行。</p><pre><code>cat &lt;&lt;EOF
set superusers=”tecmint”
Password_pbkdf2 tecmint
grub.pbkdf2.sha512....你的加密密碼....
EOF
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Encrypted-Grub-Password.jpeg" alt="加密 Grub 密碼"></p><p><em>加密 Grub 密碼</em></p><p>用你係統上生成的密碼代替原來的密碼，別忘了交叉檢查密碼。</p><p>同樣注意在這種情況下你也需要像上面那樣生成 grub.cfg。重啓並敲擊 ‘e’ 進入編輯，會提示你輸入用户名和密碼。</p><p>我們已經介紹了大部分工業標準發行版 RHEL 7 和 CentOS 7 安裝後必要的操作。如果你發現我們缺少了一些點或者你有新的東西可以擴充這篇文章，你可以和我們一起分享，我們會通過擴充在這篇文章中包括你的分享。</p><hr>`,34)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),o(n,{href:"http://www.tecmint.com/things-to-do-after-minimal-rhel-centos-7-installation/6/"},{default:r(()=>[...t[0]||(t[0]=[e("http://www.tecmint.com/things-to-do-after-minimal-rhel-centos-7-installation/6/",-1)])]),_:1})]),p("p",null,[t[5]||(t[5]=e("作者：",-1)),o(n,{href:"http://www.tecmint.com/author/avishek/"},{default:r(()=>[...t[2]||(t[2]=[e("Avishek Kumar",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),o(n,{href:"https://github.com/ictlyh"},{default:r(()=>[...t[3]||(t[3]=[e("ictlyh",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[10]||(t[10]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:r(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const _=i(m,[["render",d]]);export{T as __pageData,_ as default};
